node -e "
const ExcelJS = require('exceljs');

async function createExcel() {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Handbook');

  // Add header
  sheet.columns = [{ header: 'Extracted Text', key: 'text', width: 60 }];

  // Style the header
  sheet.getRow(1).font = { bold: true };

  // Add the extracted text lines
  sheet.addRow({ text: 'Employee Handbook' });
  sheet.addRow({ text: 'Welcome to the company. This handbook outlines our policies.' });

  await workbook.xlsx.writeFile('/workspace/handbook.xlsx');
  console.log('Created handbook.xlsx successfully');
}

createExcel().catch(console.error);
"
